 for(const row of preservation.laws)db.query("insert into expected values (?,?)").run(row.name,row.source);expect(db.query("select * from laws except select * from expected").all()).toEqual([]);expect(db.query("select * from expected except select * from laws").all()).toEqual([]);expect(db.query("select name,count(*) as count from laws group by name having count(*)<>1").all()).toEqual([]);expect(assertions).toBe(preservation.originalAssertions+preservation.addedAssertions);for(const row of preservation.laws)if(typeof row.originalAssertions==="number"){expect(row.assertions).toBeGreaterThanOrEqual(row.originalAssertions);expect(row.originalSha256).not.toBe(row.sha256);}expect(preservation.laws.filter(row=>"originalSha256"in row).map(row=>row.name).sort()).toEqual(["tool_cancellation_isolated_by_live_instance_with_same_controller_and_document","cancellation_supersession_and_saturated_app_close_are_parent_scope_constant_time","cancellation_numeric_authority_rejects_collision_capacity_and_contention_without_blocking","interrupted_cancellation_gate_preserves_original_paid_slot_and_refuses_competing_authority"].sort());const renamed=preservation.laws.filter(row=>"originalName"in row);expect(renamed).toHaveLength(1);expect(renamed[0]?.originalName).toBe("poisoned_cancellation_authority_fails_closed_without_recovery_or_waiting");
