test("cancellation laws stay with the actual admitted issuer and preserve paid authority on interruption",()=>{
 const canonical=read(resolve(plugin,"♻️cancellation/🦀️.rs")),issuer=read(resolve(plugin,"♻️cancellation/🎟️issuer/🦀️.rs")),laws=read(resolve(plugin,"♻️cancellation/🎟️issuer/🧪️tests/📜️contract/🦀️.rs"));expect(canonical).not.toContain("impl Default for ToolCancellationHandle");expect(canonical).not.toContain("fn test_begin");expect(laws).not.toContain("ToolCancellationHandle::default");expect(laws).toContain("OriginalJobFixtureCaller::admit");expect(laws).toContain("issuer.admit_step(parent,cx)");expect(laws).toContain("self.issuer.begin(key,cx)");expect(laws).toContain("original_lease_cursor_admit");expect(laws).toContain("original_lease_cursor_release");expect(laws).toContain("issuer.close_step(parent,cx)");expect(laws).toContain("caller.retire(phase())");expect(issuer).toContain('#[path="🧪️tests/📜️contract/🦀️.rs"]');
 const seen=new Set<string>();const visit=(path:string)=>{if(seen.has(path))return;seen.add(path);const source=read(path);for(const m of source.matchAll(/#\[path\s*=\s*"([^"]+)"\]|include!\("([^"]+)"\)/g)){const child=m[1]??m[2];if(!child)throw Error("Literal owner mount required");visit(resolve(dirname(path),child));}};visit(resolve(plugin,"♻️cancellation/🦀️.rs"));const texts=[...seen].map(read),bytes=texts.reduce((n,s)=>n+Buffer.byteLength(s),0),lines=texts.reduce((n,s)=>n+s.split("\n").filter(line=>line.trim()).length,0);expect(bytes).toBeLessThanOrEqual(262144);expect(lines).toBeLessThanOrEqual(4000);expect(seen.size).toBeLessThanOrEqual(32);
 expect(new Ajv({strict:true}).validate(interruptionSchema,interruption)).toBe(true);const db=new Database(":memory:");try{db.exec("create table owner(slot integer primary key,document integer,operation integer,generation integer,claim integer)");const original=interruption.original,slot=original.document%interruption.slots;db.query("insert into owner values (?,?,?,?,?)").run(slot,original.document,original.operation,original.generation,original.claim);db.exec("begin");expect(db.query("select * from owner").get()).toEqual({slot,...original});db.exec("rollback");const candidate=interruption.competing,insert=db.query("insert or ignore into owner values (?,?,?,?,?)").run(candidate.document%interruption.slots,candidate.document,candidate.operation,candidate.generation,candidate.claim);expect(Boolean(insert.changes)).toBe(interruption.expected.newAuthority);expect(db.query("select count(*) as active from owner").get()).toEqual({active:interruption.expected.active});expect(db.query("select document,operation,generation,claim from owner").get()).toEqual(original);}finally{db.close();}const old=read(resolve(root,preservation.original));expect(old).not.toContain("fn poisoned_cancellation_authority_fails_closed_without_recovery_or_waiting()");expect(laws).toContain("fn interrupted_cancellation_gate_preserves_original_paid_slot_and_refuses_competing_authority()");expect(laws).toContain("std::panic::catch_unwind");expect(laws).toContain("PublicationClaimHandle::same_original");expect(laws).toContain("assert_eq!(fixture.caller.cumulative_receipt(),receipt)");
});
