import surfaceDerivedOwnerSchema from"./🧬️surface-derived-owners.json";
import surfaceDerivedOwners from"./📋️surface-derived-owners.json";
test("actual canonical derive owners have direct fixture dependencies and exact defining trait paths",async()=>{
 expect(new Ajv({strict:true}).validate(surfaceDerivedOwnerSchema,surfaceDerivedOwners)).toBe(true);const p=await parser(),db=new Database(":memory:");try{db.exec("create table actual(path text,owner text);create table expected(path text,owner text)");for(const owner of surfaceDerivedOwners.owners)for(const source of owner.sources){const tree=p.parse(read(resolve(root,source)));try{expect(tree.rootNode.hasError()).toBe(false);for(const attr of tree.rootNode.descendantsOfType("attribute_item")){const declared=attr.text.match(/^#\[canonical_json\(owner\s*=\s*([A-Za-z_][A-Za-z0-9_]*)\)\]$/)?.[1];if(declared)db.query("insert into actual values(?,?)").run(source,declared);}db.query("insert into expected values(?,?)").run(source,owner.identifier);}finally{tree.delete();}}expect(db.query("select * from actual except select * from expected").all()).toEqual([]);expect(db.query("select * from expected except select * from actual").all()).toEqual([]);const macro=read(resolve(root,surfaceDerivedOwners.macroSource)),tree=p.parse(macro);try{expect(tree.rootNode.hasError()).toBe(false);expect(macro).toContain('owner=Some(meta.value()?.parse::<syn::Path>()?);');expect(macro).toContain('impl #implementation #owner::ArtifactCanonicalJsonTree for #name');}finally{tree.delete();}const consumer=resolve(root,surfaceDerivedOwners.consumer),dependencies=table(manifest(consumer).dependencies);for(const owner of surfaceDerivedOwners.owners){expect(dependencies[owner.package]).toBeDefined();const edge=table(dependencies[owner.package]);expect(owner.package.replaceAll("-","_")).toBe(owner.identifier);expect(resolve(dirname(consumer),String(edge.path),"Cargo.toml")).toBe(resolve(root,owner.manifest));const defining=manifest(resolve(root,owner.manifest));expect(table(defining.package).name).toBe(owner.package);expect(table(defining.lib).name).toBe(owner.identifier);const existing=((manifest(resolve(root,surfaceFixtureLock.path)).package as unknown[]).map(table)).filter(row=>row.name===owner.package);expect(existing).toHaveLength(1);expect(existing[0]?.version).toBe(table(defining.package).version);expect(existing[0]?.source).toBeUndefined();expect(existing[0]?.checksum).toBeUndefined();}}finally{p.delete();db.close();}
});
